        'terms'     => [ [ 'ROI', 'Net profit as a percentage of the cost.' ], [ 'Break-even price', 'The sell price at which profit is zero after fees.' ], [ 'Capital gain', 'The profit from selling an asset for more than you paid.' ], [ 'Cost basis', 'What you originally paid for an asset, including fees — used to calculate gain or loss when you sell.' ] ],
        'faqs'      => [
            [ 'How do you calculate crypto profit?', 'Subtract your total cost, including fees, from the sale proceeds after fees.' ],
            [ 'What is the break-even price?', 'The sell price at which you recover your purchase cost and both fees.' ],
